insert into public.course_modules (id, course_id, title, description, position) values
  ('c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', '776b1633-dd76-67f4-532f-87063a481f11', 'Auditer un système Linux', 'Lire les journaux d’un serveur Linux et repérer les droits, les comptes et les tâches planifiées dangereux.', 3),
  ('44bd6cd9-5751-ccb1-3836-e36284128600', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Investiguer un incident', 'Reconnaître une attaque dans les journaux, la relier aux autres sources et rédiger la chronologie.', 3)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('82d908d7-039d-ba6a-9023-f566d39a819f', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', 'Les journaux d’un serveur Linux', 'Savoir où Linux écrit ses journaux, lire une ligne syslog et filtrer avec grep et journalctl.', '{"blocks":[{"type":"callout","content":"Objectifs : localiser les journaux d’un serveur Linux, décomposer une ligne syslog, filtrer un fichier avec grep et interroger journald."},{"type":"text","content":"Un serveur Linux raconte tout ce qui lui arrive : connexions, commandes administrateur, démarrages de services, erreurs. Ce récit s’écrit dans des journaux. Pour un analyste, ce sont les premières preuves en cas d’incident : sans eux, impossible de savoir qui est entré, quand et ce qu’il a fait."},{"type":"callout","content":"Vidéo à venir : Où sont les journaux sous Linux et comment les lire"},{"type":"text","content":"Les fichiers de journaux sont rangés dans /var/log. Leur nom varie un peu d’une distribution à l’autre, mais les rôles sont toujours les mêmes : un fichier pour les connexions et l’authentification, un pour les messages généraux, un par service important (serveur web, base de données)."},{"type":"schema","content":"/var/log/\n  auth.log      connexions SSH, sudo, changements de compte   (Debian, Ubuntu)\n  secure        même rôle sur Red Hat, CentOS, Fedora\n  syslog        messages généraux du système\n  kern.log      noyau et matériel\n  nginx/        access.log et error.log du serveur web\n  apache2/      access.log et error.log d''Apache\n  wtmp, btmp    connexions réussies et échouées (binaires : lastb, last)"},{"type":"text","content":"Une ligne syslog a toujours la même forme : la date, le nom de la machine, le programme qui parle (avec son numéro de processus entre crochets), puis le message. Apprendre à découper une ligne en quatre morceaux vous permet de lire un journal inconnu en quelques secondes."},{"type":"code","content":"Mar 14 09:12:44 srv-app01 sshd[2210]: Failed password for invalid user guest from 198.51.100.7 port 52310 ssh2\n|______________| |________| |_______| |________________________________________________________|\n    date          machine    programme                       message","language":"text"},{"type":"text","content":"Deux outils font l’essentiel du travail. grep filtre les lignes qui contiennent un motif. journalctl interroge le journal de systemd, qui centralise les messages sur les systèmes récents : on peut y filtrer par service, par priorité ou par période. Les heures des journaux sont souvent en UTC : vérifiez-le toujours avant de comparer deux sources."},{"type":"code","content":"# Les 20 dernières lignes d''authentification\ntail -n 20 /var/log/auth.log\n# Les échecs de connexion SSH\ngrep \"Failed password\" /var/log/auth.log\n# Compter les échecs par adresse IP\ngrep \"Failed password\" /var/log/auth.log | grep -o \"from [0-9.]*\" | sort | uniq -c | sort -rn\n# journald : un service sur une période\njournalctl -u ssh --since \"2 hours ago\"\n# journald : seulement les erreurs\njournalctl -p err -b","language":"bash"},{"type":"example","content":"Exemple : une ligne sudo « COMMAND=/bin/bash » signifie qu’un utilisateur a ouvert un terminal administrateur. Ce n’est pas forcément une attaque, mais c’est une ligne à replacer dans la chronologie : qui, quand et juste après quoi ?"},{"type":"callout","content":"À retenir : un journal est une suite de preuves datées. Savoir où chercher (/var/log, journalctl) et filtrer (grep, tri, comptage) vaut mieux que tout lire ligne à ligne."}]}'::jsonb, 18, 25, 1),
  ('16e2b52c-750a-fd98-e22e-bb1228adecff', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', 'Auditer droits, comptes et tâches planifiées', 'Repérer fichiers SUID, règles sudo, comptes UID 0 et scripts cron modifiables : les portes dérobées classiques.', '{"blocks":[{"type":"callout","content":"Objectifs : lire les droits d’un fichier, repérer un fichier modifiable par tous, expliquer le risque des fichiers SUID, des règles sudo et des tâches cron, et reconnaître un compte administrateur caché."},{"type":"text","content":"Un système Linux est surtout une affaire de droits. Un attaquant qui entre avec un compte limité cherche une faille de configuration pour devenir root. L’audit consiste à passer en revue ces points faibles avant lui : fichiers trop permissifs, programmes qui s’exécutent avec les droits de leur propriétaire, règles sudo trop larges, comptes en trop."},{"type":"callout","content":"Vidéo à venir : Les 5 vérifications d’un audit Linux express"},{"type":"text","content":"Les droits d’un fichier se lisent avec ls -l. Ils se composent de trois triplets lecture (r), écriture (w), exécution (x) : propriétaire, groupe, autres. Le mode numérique correspondant s’écrit en octal : 755 signifie rwxr-xr-x. Le mode 777 donne tous les droits à tout le monde : un fichier ainsi ouvert peut être modifié par n’importe quel compte du système."},{"type":"schema","content":"-rwxr-xr-x 1 root root  1204 mars 14 09:00 /usr/local/bin/sauvegarde.sh      mode 755 : sain\n-rwxrwxrwx 1 root root   412 mars 14 09:00 /opt/scripts/nettoyage.sh         mode 777 : DANGER\n |||||||||\n |||||||||__ autres : r w x\n ||||||_____ groupe : r w x\n |||________ propriétaire : r w x"},{"type":"text","content":"Le bit SUID (affiché s à la place du x du propriétaire) fait s’exécuter un programme avec les droits de son propriétaire, souvent root. Quelques programmes légitimes l’utilisent (passwd, sudo). Un éditeur ou un outil de recherche avec le bit SUID, en revanche, permet souvent d’obtenir un terminal root : des listes publiques (GTFOBins) recensent ces détournements."},{"type":"text","content":"Troisième point : sudo. Le dossier /etc/sudoers.d contient les règles qui autorisent des comptes à lancer des commandes en administrateur. Une règle précise (« redémarrer ce service ») est saine. Une règle « NOPASSWD: ALL » donne à son bénéficiaire un accès root sans mot de passe sur tout le système."},{"type":"text","content":"Quatrième et cinquième points : les tâches planifiées et les comptes. Une tâche cron exécutée par root qui lance un script modifiable par tous est une porte ouverte : il suffit de modifier le script pour que root exécute vos commandes. Côté comptes, un seul compte doit avoir l’UID 0 (root). Tout autre compte à UID 0 est un administrateur déguisé, souvent créé pour garder un accès."},{"type":"code","content":"# Fichiers modifiables par tous (hors liens et /proc)\nfind / -xdev -type f -perm -0002 2>/dev/null\n# Fichiers avec le bit SUID\nfind / -perm -4000 -type f 2>/dev/null\n# Règles sudo\ncat /etc/sudoers.d/*\n# Tâches planifiées de root\ncrontab -l -u root\n# Comptes dont l''UID vaut 0\nawk -F: ''$3 == 0 {print $1}'' /etc/passwd","language":"bash"},{"type":"example","content":"Exemple : un cron de root lance toutes les 15 minutes /srv/maintenance/purge.sh, et ce script est en mode 777. Un compte compromis y ajoute une ligne qui crée un compte administrateur : au prochain passage, root l’exécute. Le défaut n’est pas dans cron, il est dans les droits du script."},{"type":"callout","content":"À retenir : cinq vérifications, cinq commandes. Fichiers ouverts à tous, SUID inattendus, règles sudo trop larges, scripts cron modifiables, comptes UID 0 en trop."}]}'::jsonb, 22, 30, 2),
  ('0e986745-9f83-95a0-7afe-e74ae34d8c86', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', 'Reconnaître une attaque SSH par force brute', 'Lire les échecs de connexion, repérer le moment où l’attaquant réussit et les gestes qui suivent.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître une attaque par force brute dans auth.log, distinguer un échec d’un succès, mesurer la durée d’une attaque et repérer ce que l’attaquant fait après sa connexion."},{"type":"text","content":"Un serveur exposé à Internet reçoit des tentatives de connexion SSH en permanence : ce bruit de fond est normal. Une attaque par force brute se reconnaît à son volume et à sa régularité : des dizaines d’essais en quelques minutes, depuis une même adresse, sur des comptes souvent inventés (admin, test, oracle) ou sur un compte réel."},{"type":"callout","content":"Vidéo à venir : Lire auth.log : de l’échec à la prise de contrôle"},{"type":"text","content":"Dans auth.log, chaque essai laisse une ligne. « Failed password for invalid user » signifie que le compte n’existe pas. « Failed password for backup » signifie que le compte existe, ce qui est plus inquiétant : l’attaquant a trouvé un nom valide. « Accepted password » ou « Accepted publickey » signale une connexion réussie."},{"type":"schema","content":"03:31:14  Invalid user admin from 192.0.2.150              <- compte inventé\n03:31:15  Failed password for invalid user admin ...      <- échec\n   ...      (rafale d''échecs, quelques secondes d''écart)\n03:33:41  Failed password for backup ...                  <- compte réel visé\n03:33:47  Accepted password for backup ...                <- SUCCÈS : le moment critique\n03:34:20  sudo: backup : COMMAND=/bin/bash                <- il devient root"},{"type":"text","content":"Le moment critique est le premier « Accepted » qui suit une rafale d’échecs depuis la même adresse : c’est la compromission. Tout ce qui vient après compte : nouvelle session, passage root avec sudo, création d’un compte, ajout à un groupe privilégié, modification du mot de passe. Chaque geste laisse sa propre ligne dans le journal."},{"type":"code","content":"# Qui échoue le plus ?\ngrep \"Failed password\" auth.log | grep -o \"from [0-9.]*\" | sort | uniq -c | sort -rn | head\n# Un succès venant de cette adresse ?\ngrep \"Accepted\" auth.log | grep \"192.0.2.150\"\n# Création de compte et changements de groupe\ngrep -E \"useradd|usermod|passwd\" auth.log","language":"bash"},{"type":"text","content":"Attention aux leurres. Un scanner qui tente trois fois le compte root puis abandonne n’est pas l’attaquant : il n’a rien obtenu. Il faut toujours vérifier si une adresse a réussi à entrer, pas seulement si elle a essayé. Et une connexion par clé depuis une adresse interne connue est le comportement normal des administrateurs."},{"type":"example","content":"Exemple : 40 échecs sur trois comptes inventés, puis 4 échecs sur le compte « backup », puis « Accepted password for backup » : l’attaquant a deviné le mot de passe. Trente secondes plus tard, sudo ouvre un terminal root et un compte « maintenance » est créé : c’est une persistance."},{"type":"callout","content":"À retenir : volume + régularité = force brute. Cherchez le premier succès après les échecs, puis lisez tout ce qui suit : c’est là que l’impact se mesure."}]}'::jsonb, 20, 30, 1),
  ('34eaad55-b18b-09cd-6054-961d6b991090', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', 'Lire les journaux d’un serveur web', 'Repérer un scan, une injection SQL et une porte dérobée web dans un journal d’accès.', '{"blocks":[{"type":"callout","content":"Objectifs : décomposer une ligne de journal d’accès, reconnaître un scanner, une injection SQL et un webshell, et suivre les requêtes d’une même adresse."},{"type":"text","content":"Un journal d’accès web contient une ligne par requête reçue. Le format le plus courant (combined) donne l’adresse du visiteur, l’heure, la requête (méthode et adresse demandée), le code de réponse, la taille de la réponse et le navigateur déclaré (User-Agent). Chaque ligne se lit comme une petite phrase."},{"type":"callout","content":"Vidéo à venir : Reconnaître un scan, une injection et un webshell dans un journal"},{"type":"code","content":"198.51.100.30 - - [15/Mar/2026:10:21:07 +0000] \"GET /catalogue.php?id=7 HTTP/1.1\" 200 5120 \"-\" \"Mozilla/5.0 (X11; Linux x86_64) Firefox/115.0\"\n|____________|     |____________________________|  |_____________________________|  |_|  |__|          |______________________|\n  adresse                     heure                      requête                  code taille              navigateur","language":"text"},{"type":"text","content":"Les codes de réponse racontent beaucoup. 200 : la page existe et a été servie. 301 et 302 : redirection (un 302 après un POST sur une page de connexion signale souvent une connexion réussie). 404 : la page n’existe pas. 403 : accès refusé. 500 : erreur du serveur. Une longue suite de 404 depuis une même adresse indique un scanner qui essaie des chemins connus."},{"type":"text","content":"Les scanners de vulnérabilités, comme Nikto, se déclarent parfois dans le User-Agent. Un attaquant discret change cette valeur : c’est pourquoi on regarde aussi le comportement (rythme, chemins demandés) plutôt que la seule étiquette."},{"type":"text","content":"L’injection SQL se voit dans l’adresse demandée : apostrophe encodée (%27), tests logiques (OR 1=1), tri de colonnes (ORDER BY) puis UNION SELECT pour extraire les données d’une autre table. Les requêtes se suivent à un rythme trop régulier pour un humain : c’est un outil automatique comme sqlmap."},{"type":"schema","content":"GET /catalogue.php?id=7%27                              <- l''apostrophe casse la requête\nGET /catalogue.php?id=7%20OR%201=1                      <- test logique\nGET /catalogue.php?id=7%20ORDER%20BY%205                <- compte les colonnes\nGET /catalogue.php?id=-1%20UNION%20SELECT%201,2,3,4     <- extrait des données"},{"type":"text","content":"Enfin, le webshell : un petit fichier déposé sur le serveur (souvent après un envoi de fichier détourné) qui exécute les commandes passées dans l’adresse. On le reconnaît à une requête POST d’envoi de fichier, puis à des requêtes GET répétées vers un fichier .php situé dans un dossier d’envois, avec un paramètre comme cmd=whoami."},{"type":"code","content":"# Requêtes d''une adresse\ngrep \"^198.51.100.30 \" access.log\n# Codes 404 par adresse\nawk ''$9 == 404 {print $1}'' access.log | sort | uniq -c | sort -rn\n# Signes d''injection SQL\ngrep -iE \"union|%27|or%201=1|order%20by\" access.log\n# Fichiers php appelés dans le dossier d''envois\ngrep \"/uploads/\" access.log | grep \".php\"","language":"bash"},{"type":"example","content":"Exemple : un POST sur /admin/upload.php suivi de GET /uploads/x.php?cmd=id, puis cmd=whoami : la dernière étape de la chaîne est un webshell. Le premier appel de commande donne l’heure de la prise de contrôle."},{"type":"callout","content":"À retenir : suivez une adresse du début à la fin. Scan (404 en rafale), injection (apostrophes, UNION), dépôt d’un fichier, puis commandes par un webshell : chaque étape a sa signature."}]}'::jsonb, 22, 30, 2),
  ('57de4155-e6dc-5e3b-be8f-aafc5bf84d14', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', 'Reconstituer la chronologie d’un incident', 'Relier plusieurs journaux, ordonner les événements et rédiger un rapport d’incident clair.', '{"blocks":[{"type":"callout","content":"Objectifs : corréler plusieurs sources de journaux, écarter les faux positifs, construire une chronologie ordonnée et rédiger un rapport d’incident utile."},{"type":"text","content":"Une attaque réelle ne laisse pas toutes ses traces au même endroit. Le journal web montre l’entrée, le journal d’authentification montre les rebonds, le journal de tâches planifiées montre la persistance et celui du pare-feu montre les données qui sortent. Le travail d’un analyste SOC consiste à relier ces sources pour raconter une histoire cohérente."},{"type":"callout","content":"Vidéo à venir : Du journal à la chronologie : méthode d’un analyste SOC"},{"type":"text","content":"La corrélation commence par un fil conducteur : une adresse IP, un compte, un nom de fichier. On cherche ce fil dans chaque source et on note chaque occurrence avec son heure. Mettre toutes les heures dans le même fuseau (UTC) est indispensable, sinon l’ordre des événements est faux."},{"type":"schema","content":"heure (UTC)  source        événement\n01:03:12     web          premiers échecs de connexion à l''administration\n01:04:05     web          connexion réussie           <- accès initial\n01:06:40     web          fichier déposé              <- webshell\n01:08:10     web          lecture d''un fichier de configuration\n01:15:22     ssh          connexion avec un compte de base de données   <- rebond\n01:18:50     cron         tâche planifiée créée       <- persistance\n01:27:31     pare-feu     connexion sortante vers l''attaquant   <- exfiltration"},{"type":"text","content":"Les faux positifs encombrent tous les journaux : une administratrice qui se connecte depuis le bureau, un scanner qui échoue, un script de sauvegarde. Pour les écarter, posez-vous trois questions : l’adresse est-elle connue ? Y a-t-il eu un succès ? L’action est-elle cohérente avec le reste de l’attaque ? Un événement qui répond « oui, non, non » n’appartient pas à l’histoire."},{"type":"text","content":"Une chronologie utile suit le cycle d’une intrusion : accès initial (comment il est entré), exécution (ce qu’il a lancé), rebond (autres comptes ou machines touchés), persistance (comment il compte revenir), exfiltration (ce qui est sorti). Pour chaque étape, notez l’heure, la preuve (la ligne du journal) et l’impact."},{"type":"code","content":"# Toutes les occurrences d''une adresse, toutes sources confondues, triées par heure\ngrep -h \"192.0.2.60\" web.log ssh.log fw.log | sort\n# Fichiers déposés\ngrep -h \"upload\" web.log\n# Tâches planifiées créées ou modifiées\ngrep -h \"crontab\" auth.log","language":"bash"},{"type":"text","content":"Le rapport se lit par des gens pressés. Commencez par un résumé de trois lignes : ce qui s’est passé, depuis quand, quel impact. Puis donnez la chronologie avec les preuves, les comptes et machines touchés, et enfin les actions de remédiation : changer les mots de passe, supprimer la persistance, fermer l’accès initial, bloquer l’adresse, surveiller la sortie de données."},{"type":"example","content":"Exemple : « Le 2 avril à 01:04 UTC, l’adresse 192.0.2.60 s’est connectée à l’administration du site après 9 échecs. Elle a déposé un webshell puis s’est connectée en SSH avec un compte de base de données. Une tâche planifiée assure son retour. Un transfert sortant a été observé à 01:27. » Voilà le résumé d’un rapport."},{"type":"callout","content":"À retenir : un fil conducteur, une seule échelle de temps, des preuves citées, et un rapport qui commence par l’essentiel. Écartez les faux positifs, sans les oublier : citez-les comme éliminés."}]}'::jsonb, 22, 30, 3)
insert into public.quizzes (id, course_id, module_id, lesson_id, title, pass_percentage, position) values
  ('84f03cb0-740f-2880-bf27-c953de89ebe6', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', '82d908d7-039d-ba6a-9023-f566d39a819f', 'Quiz : les journaux d’un serveur Linux', 70, 1),
  ('1bb1fc2f-4fac-680e-7e54-8e778363b316', '776b1633-dd76-67f4-532f-87063a481f11', 'c79314fa-4ab0-cdb2-daee-16b4b6c1dbc3', '16e2b52c-750a-fd98-e22e-bb1228adecff', 'Quiz : auditer droits, comptes et tâches planifiées', 70, 2),
  ('708b3ffe-3c44-ee91-a659-a3d8dd195e20', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', '0e986745-9f83-95a0-7afe-e74ae34d8c86', 'Quiz : attaque SSH par force brute', 70, 1),
  ('91f7971e-55d3-e149-4b4f-c0abc921d9ac', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', '34eaad55-b18b-09cd-6054-961d6b991090', 'Quiz : journaux d’un serveur web', 70, 2),
  ('e13b6544-0809-784a-5b48-b4a772417393', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '44bd6cd9-5751-ccb1-3836-e36284128600', '57de4155-e6dc-5e3b-be8f-aafc5bf84d14', 'Quiz : chronologie d’un incident', 70, 3)
insert into public.quiz_questions (id, quiz_id, position, question_type, prompt, explanation, difficulty, xp_reward) values
  ('8bac24ab-8470-7748-681f-c191c6b8b1bb', '84f03cb0-740f-2880-bf27-c953de89ebe6', 1, 'single_choice', 'Quel fichier enregistre les connexions SSH et les commandes sudo sur Debian et Ubuntu ?', 'auth.log centralise l’authentification : connexions SSH, sudo, changements de compte. Sur Red Hat, le fichier équivalent s’appelle secure.', 'facile', 10),
  ('8c0b0f2d-c7ef-40e5-e4a9-e00f358239f3', '84f03cb0-740f-2880-bf27-c953de89ebe6', 2, 'single_choice', 'Quelle commande affiche seulement les lignes contenant « Failed password » ?', 'grep filtre les lignes d’un fichier selon un motif : c’est l’outil de base de l’analyse de journaux.', 'facile', 10),
  ('210f23cb-a570-4f4f-b0f1-fd6f8cd278e9', '84f03cb0-740f-2880-bf27-c953de89ebe6', 3, 'true_false', 'Les heures d’un journal sont toujours exprimées dans le fuseau horaire de l’analyste.', 'Les serveurs journalisent souvent en UTC. Il faut vérifier le fuseau avant de comparer plusieurs sources.', 'moyen', 10),
  ('e47f2268-c977-5078-e5be-0f43d7ad539b', '1bb1fc2f-4fac-680e-7e54-8e778363b316', 1, 'single_choice', 'Que signifie le mode 777 sur un script ?', '7 correspond à rwx : lecture, écriture et exécution pour le propriétaire, le groupe et les autres.', 'facile', 10),
  ('eba8167f-5f57-6184-7d83-3e259ba2c403', '1bb1fc2f-4fac-680e-7e54-8e778363b316', 2, 'single_choice', 'Pourquoi un script en mode 777 lancé par le cron de root est-il dangereux ?', 'Root exécute le script avec tous les droits : celui qui peut le modifier peut donc faire exécuter ce qu’il veut à root.', 'moyen', 10),
  ('d0c93d2d-b4cc-109d-a406-cf67e40ec721', '1bb1fc2f-4fac-680e-7e54-8e778363b316', 3, 'true_false', 'Un compte autre que root dont l’UID vaut 0 est un signe d’alerte.', 'L’UID 0 donne tous les droits. Un compte supplémentaire à UID 0 est un administrateur caché, souvent créé pour garder un accès.', 'moyen', 10),
  ('2cc5e466-59aa-d911-8028-f3fb075df076', '708b3ffe-3c44-ee91-a659-a3d8dd195e20', 1, 'single_choice', 'Quelle ligne marque le moment où l’attaquant entre ?', 'Les échecs montrent l’attaque. Le premier succès depuis la même adresse montre qu’elle a réussi.', 'facile', 10),
  ('6d811599-3e2e-c513-a999-e6e3915bff1e', '708b3ffe-3c44-ee91-a659-a3d8dd195e20', 2, 'single_choice', 'Une adresse tente trois fois root, échoue et disparaît. Que conclure ?', 'Sans aucun « Accepted » pour cette adresse, rien ne prouve qu’elle est entrée. Ne confondez pas bruit et attaque.', 'moyen', 10),
  ('58a68572-fc36-0299-050b-75325a433c35', '708b3ffe-3c44-ee91-a659-a3d8dd195e20', 3, 'true_false', '« Failed password for invalid user » prouve que le compte visé existe.', '« invalid user » signifie au contraire que le compte n’existe pas : l’attaquant devine des noms.', 'moyen', 10),
  ('f2842ca5-83c2-acdd-d940-e4dad4711965', '91f7971e-55d3-e149-4b4f-c0abc921d9ac', 1, 'single_choice', 'Une adresse reçoit des dizaines de 404 en quelques secondes. Que suggère ce motif ?', 'Un humain ne demande pas des dizaines de pages inexistantes à la suite : c’est le comportement d’un scanner.', 'facile', 10),
  ('222355ec-7ede-f674-0d33-3450758b1e42', '91f7971e-55d3-e149-4b4f-c0abc921d9ac', 2, 'single_choice', 'Que révèle une requête avec « UNION SELECT » dans l’adresse ?', 'UNION SELECT sert à greffer une seconde requête SQL pour lire d’autres tables : c’est une injection.', 'moyen', 10),
  ('ff6dbf88-f0f3-77d2-1cd9-42c4ff3e3a18', '91f7971e-55d3-e149-4b4f-c0abc921d9ac', 3, 'single_choice', 'Quelle séquence signale un webshell ?', 'Le fichier déposé s’exécute ensuite par des requêtes GET qui transportent les commandes à lancer.', 'moyen', 10),
  ('22488489-0484-25e8-b9d8-ca640be23819', 'e13b6544-0809-784a-5b48-b4a772417393', 1, 'single_choice', 'Quelle première précaution avant de comparer les événements de plusieurs journaux ?', 'Si une source est en UTC et une autre en heure locale, l’ordre des événements est faux.', 'facile', 10),
  ('9658e62a-97d7-caa2-940a-50999f896c7e', 'e13b6544-0809-784a-5b48-b4a772417393', 2, 'single_choice', 'Dans quelle étape range-t-on la création d’une tâche cron qui relance un script chaque heure ?', 'La tâche planifiée garantit que l’attaquant garde un accès même après un redémarrage ou un changement de mot de passe.', 'moyen', 10),
  ('94da08c3-adf2-4f72-60f1-d23d0f7e8990', 'e13b6544-0809-784a-5b48-b4a772417393', 3, 'true_false', 'Un rapport d’incident doit commencer par la liste complète des lignes de journal.', 'Un rapport commence par un résumé court : ce qui s’est passé, depuis quand, quel impact. Les preuves détaillées viennent ensuite.', 'facile', 10)
