insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('68349abe-2454-80cc-e092-781462c23724', 'audit-linux-droits', 'Audit Linux : droits, sudo et cron', 'Un serveur de comptabilité vient d’être repris par ton équipe. Passe en revue les droits, les règles sudo, les tâches cron et les comptes pour trouver ce qui ne va pas.', 'linux', 'debutant', 120, array['Repérer un fichier modifiable par tous', 'Relier un script dangereux à une tâche cron de root', 'Identifier un fichier SUID qui ne devrait pas l’être', 'Détecter une règle sudo trop large et un compte administrateur caché']::text[], array['Les sections du fichier sont séparées par un en-tête qui rappelle la commande exécutée.', 'Un mode qui finit par 7 donne tous les droits à tout le monde.', 'Dans /etc/passwd, le troisième champ est l’UID : cherche 0 hors du compte root.']::text[], '{}'::text[], 200, '776b1633-dd76-67f4-532f-87063a481f11', 'logs', 'Le serveur srv-compta01 héberge la comptabilité de l’atelier Kora. L’ancien administrateur est parti sans documentation. Avant d’ouvrir le serveur au reste du réseau, ton responsable te demande un audit express. Tu disposes de la sortie des cinq commandes d’audit classiques, enregistrées dans un seul fichier : permissions d’un script, fichiers SUID, règles sudo, tâches cron de root et comptes du système. Ta mission : repérer ce qui permettrait à un utilisateur ordinaire de devenir administrateur.', array['Analyse uniquement le fichier fourni : n’exécute rien sur un système réel.', 'Cite la ligne qui prouve chaque réponse.']::text[], array['Visionneuse de journaux CyberPingo', 'grep (facultatif)', 'Guide : audit Linux en cinq vérifications']::text[], false, false, 25),
  ('09d222fa-0ecf-adf9-c4ef-51d24b215a04', 'brute-force-ssh', 'Force brute SSH : de l’échec à la prise de contrôle', 'Le serveur web a subi une rafale de tentatives SSH pendant la nuit. Retrouve l’attaquant, le moment où il entre et ce qu’il fait ensuite.', 'securite', 'intermediaire', 150, array['Trouver l’adresse la plus agressive', 'Identifier le compte réel visé', 'Dater l’entrée et mesurer la durée de l’attaque', 'Repérer la persistance : compte créé et groupe']::text[], array['Filtre sur « Failed password » puis compte par adresse : l’attaquant cumule des dizaines d’échecs.', 'Cherche « Accepted » : une connexion par mot de passe depuis une adresse externe est suspecte.', 'Après le succès, cherche useradd et usermod.']::text[], '{}'::text[], 210, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le serveur web-srv01 sert le site de la boutique. À 08 h, l’équipe de supervision signale un compte inattendu sur la machine. Le fichier auth.log de la nuit est disponible. Il mélange les connexions normales des administrateurs (par clé, depuis le réseau interne) et du bruit venu d’Internet. Ta mission : identifier l’adresse qui a mené l’attaque, le compte qu’elle visait, le moment exact où elle est entrée, puis ce qu’elle a fait après, sans te laisser piéger par un scanner inoffensif.', array['Ne conclus que ce que le journal prouve.', 'Les heures sont en UTC, sur une seule nuit.', 'Une adresse qui échoue sans jamais réussir n’est pas forcément l’attaquant.']::text[], array['Visionneuse de journaux CyberPingo', 'grep, sort et uniq (facultatif)', 'Guide : lire un journal d’incident']::text[], false, false, 30),
  ('a4936653-9d20-d596-9a81-082087f0d3ea', 'intrusion-web', 'Intrusion web : du scan au webshell', 'Une page de la boutique en ligne a été exploitée. Dans le journal d’accès, retrouve l’outil de scan, l’injection SQL, la prise d’accès et la porte dérobée.', 'securite', 'intermediaire', 160, array['Identifier l’adresse et l’outil du scan', 'Trouver la page vulnérable à l’injection SQL', 'Dater la connexion à l’administration', 'Retrouver le webshell et le premier ordre exécuté']::text[], array['Le scanner se déclare souvent dans le dernier champ de la ligne (le User-Agent).', 'Les requêtes d’injection contiennent %27, UNION ou ORDER BY.', 'Un POST sur la page de connexion suivi d’un 302 signale une connexion réussie.']::text[], '{}'::text[], 220, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le site de la boutique tourne sur un serveur Apache. Le client constate que des pages d’administration ont été modifiées. Le journal d’accès de la nuit contient le trafic normal des visiteurs et plusieurs comportements anormaux : un scanner, une série de requêtes étranges sur une page de produits, un envoi de fichier. Ta mission : reconstituer les étapes de l’attaque, de la reconnaissance jusqu’aux premières commandes exécutées sur le serveur.', array['Suis l’adresse suspecte du début à la fin.', 'Les heures sont en UTC.', 'Une adresse qui fait des fautes de frappe n’est pas un attaquant.']::text[], array['Visionneuse de journaux CyberPingo', 'grep, awk et sort (facultatif)', 'Guide : lire un journal d’incident']::text[], false, false, 30),
  ('df158b04-9a9d-f44f-e2a5-d3366dd066eb', 'investigation-soc', 'Investigation SOC : reconstituer une intrusion complète', 'Évaluation finale. Trois heures de journaux consolidés du serveur web et du pare-feu : retrouve l’accès initial, le rebond, la persistance et la sortie de données.', 'securite', 'avance', 250, array['Trouver l’adresse de l’attaquant et le compte compromis', 'Dater l’accès initial et décrire l’exécution', 'Identifier le rebond et la persistance', 'Repérer la sortie de données et sa destination']::text[], array['Commence par les échecs d’authentification : une même adresse en cumule beaucoup.', 'L’accès initial est la première connexion réussie après ces échecs.', 'Pour la persistance, cherche crontab et un script placé dans /tmp.', 'Pour l’exfiltration, filtre le journal du pare-feu sur ALLOW OUT.']::text[], '{}'::text[], 230, '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'logs', 'Le SOC a consolidé en un seul fichier les journaux du serveur web web-srv01 (nginx, ssh, cron) et du pare-feu fw01. Chaque ligne suit le format « horodatage ISO, machine, service, message ». Une intrusion s’est produite dans la nuit. Elle se mêle à du trafic normal et à plusieurs faux positifs : une administratrice qui se connecte depuis le bureau, un scanner qui échoue. Ta mission : reconstituer toute la chaîne (accès initial, exécution, rebond, persistance, exfiltration) avec une preuve pour chaque étape. Le modèle de rapport d’incident peut t’aider à structurer tes conclusions.', array['Chaque réponse doit s’appuyer sur une ligne du fichier.', 'Les heures sont en UTC (suffixe Z).', 'Écarte les faux positifs en vérifiant s’il y a eu un succès.', 'Le rapport fourni est un modèle : il ne remplace pas les réponses ci-dessous.']::text[], array['Visionneuse de journaux CyberPingo', 'grep, sort et uniq (facultatif)', 'Modèle de rapport d’incident', 'Guide : lire un journal d’incident']::text[], false, true, 45)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('dbbf4f48-95e0-d0c8-0ded-224bd2e8efe4', '68349abe-2454-80cc-e092-781462c23724', 1, 'Quel script est modifiable par tous les utilisateurs du système ?', 'Regarde la sortie de ls -l : cherche rwxrwxrwx.', 'Chemin complet, par exemple /opt/tools/script.sh'),
  ('175c46b8-bda3-e227-8b60-c6bb755d3889', '68349abe-2454-80cc-e092-781462c23724', 2, 'Quel est le mode numérique de ce script ?', 'Chaque triplet rwx vaut 7.', 'Trois chiffres'),
  ('390d168b-d94d-4eec-c6a3-fbcdbbb38984', '68349abe-2454-80cc-e092-781462c23724', 3, 'Quel compte lance ce script par une tâche cron ?', 'Lis la sortie de crontab -l -u root.', 'Nom du compte'),
  ('5b6d52e3-8b06-cb12-0c02-a8276eca95a7', '68349abe-2454-80cc-e092-781462c23724', 4, 'Toutes les combien de minutes cette tâche s’exécute-t-elle ?', 'Le premier champ de la ligne cron est celui des minutes : */n signifie « toutes les n minutes ».', 'Un nombre entier'),
  ('ef507c4e-c576-eb22-fd3d-600ce3c5cc05', '68349abe-2454-80cc-e092-781462c23724', 5, 'Combien de fichiers SUID la commande find liste-t-elle au total ?', 'Compte les lignes de la section « find / -perm -4000 ».', 'Un nombre entier'),
  ('0c23e008-e216-fe1d-8c17-64c8df5d8016', '68349abe-2454-80cc-e092-781462c23724', 6, 'Quel fichier SUID est un outil de recherche qui permet d’obtenir un terminal root ?', 'Parmi les outils de la liste, un seul sert à chercher des fichiers.', 'Chemin complet ou nom du programme'),
  ('b4200ca8-c436-d5ee-43e7-becd328a9ebb', '68349abe-2454-80cc-e092-781462c23724', 7, 'Quel compte dispose d’une règle sudo « NOPASSWD: ALL » ?', 'Lis la section /etc/sudoers.d : la règle large est celle qui finit par ALL.', 'Nom du compte'),
  ('b2e6e70a-bcec-a4ac-0f33-bb87c35ae53d', '68349abe-2454-80cc-e092-781462c23724', 8, 'Quel compte, autre que root, a l’UID 0 ?', 'Le troisième champ de /etc/passwd est l’UID. La commande awk de la dernière section liste les comptes concernés.', 'Nom du compte'),
  ('b9727c5e-2638-41cb-a939-7cd7dc0eb4a1', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 1, 'Quelle adresse IP cumule le plus de lignes « Failed password » ?', 'Filtre sur Failed password et compte par adresse source.', 'Adresse IPv4'),
  ('2a087c0c-628c-b012-2a2d-ef2a8f9a2002', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 2, 'Combien de lignes « Failed password » cette adresse a-t-elle laissées au total ?', 'Compte les lignes, y compris celles pour « invalid user ».', 'Un nombre entier'),
  ('b5651235-3a33-7364-e497-6a86a49dfa24', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 3, 'Quel compte réel (qui existe sur la machine) l’attaquant a-t-il visé ?', 'Les comptes inventés sont marqués « invalid user ». Cherche l’échec qui ne l’est pas.', 'Nom du compte'),
  ('20e1d8a6-01a2-26ad-68e0-7303e1e0a477', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 4, 'À quelle heure (UTC, HH:MM:SS) l’attaque commence-t-elle, première ligne de l’attaquant ?', 'C’est la première ligne qui contient son adresse.', 'HH:MM:SS'),
  ('45a2d888-8b27-8048-e93e-c9728fdebb03', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 5, 'À quelle heure (UTC, HH:MM:SS) l’attaquant réussit-il à se connecter ?', 'Cherche « Accepted » avec l’adresse de l’attaquant.', 'HH:MM:SS'),
  ('e60fded9-945f-5dbe-e0e8-1608a00b5a78', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 6, 'Combien de secondes séparent la première ligne de l’attaquant de sa connexion réussie ?', 'Soustrais les deux heures.', 'Un nombre entier de secondes'),
  ('8a90ff94-b7f5-ff51-61a6-e401d7618bb0', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 7, 'Quel compte l’attaquant crée-t-il ensuite pour garder un accès ?', 'Cherche la ligne useradd après la connexion.', 'Nom du compte'),
  ('e418c626-f04e-39d5-c9b2-bcfedad17858', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 8, 'À quel groupe ce compte est-il ajouté, ce qui lui donne des droits d’administration ?', 'Cherche la ligne usermod.', 'Nom du groupe'),
  ('a9aab7e4-5e25-bdc2-cce1-d6584f69e9e8', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 9, 'Quelle adresse IP a tenté root trois fois, sans jamais réussir ?', 'C’est la deuxième adresse qui échoue, avec très peu de lignes.', 'Adresse IPv4'),
  ('f524926f-9748-3421-f62f-000ff737ef6a', 'a4936653-9d20-d596-9a81-082087f0d3ea', 1, 'Quel outil de scan de vulnérabilités s’identifie dans le User-Agent des requêtes qui génèrent des 404 ?', 'Regarde le dernier champ des lignes de la rafale de 404.', 'Nom de l’outil'),
  ('9dbed5e9-7878-7daa-35f2-481f9f347a82', 'a4936653-9d20-d596-9a81-082087f0d3ea', 2, 'Quelle adresse IP lance ce scan puis les attaques qui suivent ?', 'C’est la source des requêtes du scanner.', 'Adresse IPv4'),
  ('734e015f-0016-db47-220f-16d08e68bb59', 'a4936653-9d20-d596-9a81-082087f0d3ea', 3, 'Quelle page du site est la cible de l’injection SQL ?', 'Les requêtes avec %27 et UNION visent toutes la même page.', 'Chemin de la page, par exemple /page.php'),
  ('24cba06a-c62c-78d5-3f62-21f58ee106b9', 'a4936653-9d20-d596-9a81-082087f0d3ea', 4, 'Combien de requêtes contiennent « UNION » dans leur adresse ?', 'Filtre sur UNION, sans tenir compte de la casse.', 'Un nombre entier'),
  ('8c6f5ab3-df30-5cba-7b4e-571a01d29008', 'a4936653-9d20-d596-9a81-082087f0d3ea', 5, 'À quelle heure (UTC, HH:MM:SS) la première requête d’injection est-elle envoyée ?', 'Cherche la première requête avec %27 de l’attaquant.', 'HH:MM:SS'),
  ('06cf6f72-9fcb-0624-bb9c-d85f035c9b9a', 'a4936653-9d20-d596-9a81-082087f0d3ea', 6, 'À quelle heure (UTC, HH:MM:SS) l’attaquant se connecte-t-il à la page d’administration ?', 'Cherche POST /admin/login.php suivi d’un code 302.', 'HH:MM:SS'),
  ('9c16f016-4850-324a-70fd-6866b8e013a5', 'a4936653-9d20-d596-9a81-082087f0d3ea', 7, 'Quel est le chemin du webshell que l’attaquant dépose puis appelle ?', 'Il apparaît dans le dossier d’envois, juste après un POST d’envoi de fichier.', 'Chemin du fichier'),
  ('31f2f72b-5493-e93a-c240-b9efcf225a26', 'a4936653-9d20-d596-9a81-082087f0d3ea', 8, 'À quelle heure (UTC, HH:MM:SS) la première commande est-elle exécutée via ce webshell ?', 'C’est la première requête sur le webshell qui contient ?cmd=.', 'HH:MM:SS'),
  ('cc299a30-404e-afe5-4991-3b641b630fc6', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 1, 'Quelle adresse IP externe a mené l’attaque, du premier échec de connexion à l’exfiltration ?', 'Cherche la source qui cumule des échecs d’authentification puis les requêtes suspectes.', 'Adresse IPv4'),
  ('9f15099e-e346-4f19-15fc-f5babb63b0ef', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 2, 'Combien d’échecs de connexion à l’administration web précèdent la réussite ?', 'Compte les lignes auth=FAILED de l’attaquant sur le serveur web.', 'Un nombre entier'),
  ('0c7088ff-0699-c8cb-49d5-10911e1edbd1', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 3, 'Quel compte web a été compromis ?', 'Lis le champ user= de la première ligne auth=SUCCESS de l’attaquant.', 'Nom du compte'),
  ('828bd5f8-a5bc-d470-54fe-f7bdb3ae0825', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 4, 'À quelle heure (UTC, HH:MM:SS) l’attaquant obtient-il son accès initial ?', 'C’est la première ligne auth=SUCCESS depuis son adresse.', 'HH:MM:SS'),
  ('f343a1de-4da8-f4b8-e2d5-7c786e6a28a3', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 5, 'Quel est le chemin du webshell déposé sur le serveur web ?', 'Cherche le POST d’envoi de fichier, puis la page appelée avec un paramètre c=.', 'Chemin du fichier'),
  ('ae8059d0-1eba-ce62-0b08-f9658118fb50', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 6, 'Quel fichier de configuration l’attaquant lit-il avec son webshell pour récupérer des identifiants ?', 'Cherche la commande cat dans le paramètre c=.', 'Nom du fichier'),
  ('ec499b29-a349-b55a-303e-ebc26dc7082b', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 7, 'Quel autre compte l’attaquant utilise-t-il pour se connecter en SSH (le rebond) ?', 'Cherche « Accepted password » avec l’adresse de l’attaquant.', 'Nom du compte'),
  ('d957fe6e-0e5b-bc7b-58e2-6743a0a9ef1b', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 8, 'Quel fichier est lancé périodiquement pour garder un accès (la persistance) ?', 'Cherche les lignes CRON qui lancent un script placé dans /tmp.', 'Chemin du fichier'),
  ('3c36df8d-2c3b-0206-1673-6fab80ee7df8', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 9, 'Quel mécanisme du système l’attaquant utilise-t-il pour planifier ce script ?', 'Le service qui journalise l’édition est celui de la planification.', 'Nom du mécanisme'),
  ('5579166f-b9b6-113b-da84-056a33d8a488', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 10, 'À quelle heure (UTC, HH:MM:SS) la première connexion sortante vers l’adresse de l’attaquant apparaît-elle dans le pare-feu ?', 'Filtre sur ALLOW OUT et l’adresse de l’attaquant.', 'HH:MM:SS'),
  ('deb9a0f8-c0ba-8dcf-59f2-95ac9afa3058', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 11, 'Vers quel port de destination ces transferts sortants sont-ils envoyés ?', 'Lis le champ DPT= des lignes ALLOW OUT.', 'Numéro de port')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('dbbf4f48-95e0-d0c8-0ded-224bd2e8efe4', array['/opt/scripts/backup.sh', 'opt/scripts/backup.sh']::text[], 'Le script /opt/scripts/backup.sh est en mode 777 : n’importe quel compte peut le réécrire.'),
  ('175c46b8-bda3-e227-8b60-c6bb755d3889', array['777', 'rwxrwxrwx']::text[], 'rwx pour le propriétaire, le groupe et les autres donne 777. Un script exécuté par un compte privilégié ne devrait jamais être ouvert ainsi.'),
  ('390d168b-d94d-4eec-c6a3-fbcdbbb38984', array['root']::text[], 'La tâche appartient à root. Il exécute le script avec tous les droits : en le modifiant, un simple utilisateur fait exécuter ses commandes à root.'),
  ('5b6d52e3-8b06-cb12-0c02-a8276eca95a7', array['10']::text[], 'La planification */10 * * * * lance le script toutes les 10 minutes : la fenêtre pour exploiter la faille est courte.'),
  ('ef507c4e-c576-eb22-fd3d-600ce3c5cc05', array['11']::text[], 'Il y a 11 fichiers SUID. La plupart sont légitimes (passwd, sudo, mount) : l’audit consiste à repérer celui qui n’a rien à faire là.'),
  ('0c23e008-e216-fe1d-8c17-64c8df5d8016', array['/usr/bin/find', 'find']::text[], '/usr/bin/find avec le bit SUID permet de lancer une commande avec les droits de root (option -exec). C’est un détournement classique, à retirer avec chmod u-s.'),
  ('b4200ca8-c436-d5ee-43e7-becd328a9ebb', array['devops']::text[], 'devops peut tout exécuter en root sans mot de passe. Une règle limitée à une commande précise, comme celle du compte compta, est saine ; celle-ci non.'),
  ('b2e6e70a-bcec-a4ac-0f33-bb87c35ae53d', array['toor']::text[], 'Le compte toor a l’UID 0 : c’est un second root, au nom proche (root à l’envers). Les 2 comptes à UID 0 de la liste sont un signe d’alerte.'),
  ('b9727c5e-2638-41cb-a939-7cd7dc0eb4a1', array['203.0.113.45']::text[], '203.0.113.45 cumule 44 échecs : c’est la source de la rafale. L’autre adresse qui échoue n’en compte que 3.'),
  ('2a087c0c-628c-b012-2a2d-ef2a8f9a2002', array['44']::text[], 'Il y a 44 échecs, répartis sur 10 comptes inventés et un compte réel.'),
  ('b5651235-3a33-7364-e497-6a86a49dfa24', array['deploy']::text[], 'Les lignes « Failed password for deploy » (sans « invalid user ») prouvent que le compte existe : 24 tentatives ont été faites dessus.'),
  ('20e1d8a6-01a2-26ad-68e0-7303e1e0a477', array['02:14:07', '02:14:07z']::text[], 'La première ligne de l’attaquant est à 02:14:07 : un essai sur un compte inventé.'),
  ('45a2d888-8b27-8048-e93e-c9728fdebb03', array['02:16:07', '02:16:07z']::text[], 'La ligne « Accepted password for deploy » est à 02:16:07. C’est le moment de la compromission. L’attaque aura duré 120 secondes.'),
  ('e60fded9-945f-5dbe-e0e8-1608a00b5a78', array['120']::text[], 'De 02:14:07 à 02:16:07, il s’écoule 120 secondes. Aucune limite de tentatives ne l’a freiné.'),
  ('8a90ff94-b7f5-ff51-61a6-e401d7618bb0', array['support']::text[], 'Le compte support est créé quelques secondes après l’ouverture d’un terminal root avec sudo : c’est une persistance.'),
  ('e418c626-f04e-39d5-c9b2-bcfedad17858', array['sudo']::text[], 'Le compte est ajouté au groupe sudo : il peut désormais lancer des commandes en administrateur.'),
  ('a9aab7e4-5e25-bdc2-cce1-d6584f69e9e8', array['192.0.2.88']::text[], '192.0.2.88 est un scanner : 3 échecs sur root puis une fermeture avant authentification. Aucun « Accepted » : ce n’est pas l’intrusion.'),
  ('f524926f-9748-3421-f62f-000ff737ef6a', array['nikto']::text[], 'Le User-Agent annonce nikto (un scanner de serveurs web très connu). Il teste des chemins courants : d’où les 404.'),
  ('9dbed5e9-7878-7daa-35f2-481f9f347a82', array['198.51.100.23']::text[], '198.51.100.23 cumule 31 requêtes dont 12 réponses 404. L’autre adresse en 404, 192.0.2.77, fait de simples fautes de frappe.'),
  ('734e015f-0016-db47-220f-16d08e68bb59', array['/produits.php', 'produits.php']::text[], '/produits.php reçoit 8 requêtes d’injection, dont 3 avec UNION SELECT pour extraire des données.'),
  ('24cba06a-c62c-78d5-3f62-21f58ee106b9', array['3']::text[], '3 requêtes UNION SELECT : l’attaquant a compté les colonnes avec ORDER BY, puis extrait des données d’une autre table.'),
  ('8c6f5ab3-df30-5cba-7b4e-571a01d29008', array['03:47:40', '03:47:40z']::text[], 'La première injection est à 03:47:40 : une simple apostrophe pour faire échouer la requête SQL et confirmer la faille.'),
  ('06cf6f72-9fcb-0624-bb9c-d85f035c9b9a', array['03:55:12', '03:55:12z']::text[], 'Le POST sur la page de connexion à 03:55:12 reçoit un 302 : l’attaquant s’est authentifié, probablement avec des identifiants extraits par l’injection.'),
  ('9c16f016-4850-324a-70fd-6866b8e013a5', array['/uploads/shell.php', 'uploads/shell.php']::text[], '/uploads/shell.php est appelé 6 fois : une fois pour le tester, puis pour exécuter des commandes passées dans le paramètre cmd.'),
  ('31f2f72b-5493-e93a-c240-b9efcf225a26', array['03:56:47', '03:56:47z']::text[], 'À 03:56:47, la requête ?cmd=id vérifie sous quel compte tourne le serveur web. C’est le premier ordre exécuté.'),
  ('cc299a30-404e-afe5-4991-3b641b630fc6', array['203.0.113.166']::text[], '203.0.113.166 apparaît du premier échec jusqu’à la destination du transfert sortant : elle relie toutes les étapes.'),
  ('9f15099e-e346-4f19-15fc-f5babb63b0ef', array['14']::text[], '14 échecs : une attaque par force brute sur le compte admin. Le premier est à 02:09:55.'),
  ('0c7088ff-0699-c8cb-49d5-10911e1edbd1', array['admin']::text[], 'Le compte admin est aussi celui de la vraie administratrice : l’attaquant a deviné son mot de passe, ce qui explique pourquoi sa connexion paraît légitime.'),
  ('828bd5f8-a5bc-d470-54fe-f7bdb3ae0825', array['02:10:47', '02:10:47z']::text[], 'L’accès initial est à 02:10:47. La connexion légitime de l’administratrice, plus tôt dans la nuit, vient d’une adresse interne : ce n’est pas la même.'),
  ('f343a1de-4da8-f4b8-e2d5-7c786e6a28a3', array['/media/thumb.php', 'media/thumb.php']::text[], '/media/thumb.php est déposé à 02:12:21 via la fonction d’envoi de l’administration, puis appelé avec c= pour lancer des commandes.'),
  ('ae8059d0-1eba-ce62-0b08-f9658118fb50', array['config.php', '/var/www/html/config.php']::text[], 'Il lit config.php, qui contient les identifiants de la base de données. C’est ce qui lui permet ensuite de se connecter avec un autre compte.'),
  ('ec499b29-a349-b55a-303e-ebc26dc7082b', array['dbadmin']::text[], 'La connexion SSH avec dbadmin à 02:22:15 réutilise les identifiants trouvés dans config.php : le rebond.'),
  ('d957fe6e-0e5b-bc7b-58e2-6743a0a9ef1b', array['/tmp/.sync.sh']::text[], 'Le script /tmp/.sync.sh est téléchargé puis planifié avec crontab : il est relancé toutes les dix minutes.'),
  ('3c36df8d-2c3b-0206-1673-6fab80ee7df8', array['crontab', 'cron']::text[], 'La modification de la table de planification (crontab) assure la persistance, même si le mot de passe du compte change.'),
  ('5579166f-b9b6-113b-da84-056a33d8a488', array['02:30:12', '02:30:12z']::text[], 'À 02:30:12, le pare-feu laisse sortir une première grosse connexion. Elle sera répétée 4 fois : c’est l’exfiltration.'),
  ('deb9a0f8-c0ba-8dcf-59f2-95ac9afa3058', array['8443']::text[], 'Le port 8443 est inhabituel pour du trafic de bureau : c’est un canal de sortie choisi par l’attaquant.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('56d7c424-c3bd-4206-a50e-cf8f8252e475', '68349abe-2454-80cc-e092-781462c23724', 'log', 'Audit de srv-compta01 (audit-linux-serveur.log)', '53 lignes : permissions, fichiers SUID, règles sudo, tâches cron et comptes du système.', '/labs/audit-linux-serveur.log', 1),
  ('fb6f7178-8856-e8ae-a4cb-5f09e1254e4f', '68349abe-2454-80cc-e092-781462c23724', 'guide', 'Guide : audit Linux en cinq vérifications', 'Les commandes et les critères d’un audit Linux express.', '/labs/guide-audit-linux.md', 2),
  ('a347fa98-763e-382c-f920-597d799b19cf', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 'log', 'Journal d’authentification de web-srv01 (auth-ssh-web-srv01.log)', '92 lignes sur une nuit : connexions par clé, rafale d’échecs, une connexion réussie et ses conséquences.', '/labs/auth-ssh-web-srv01.log', 1),
  ('7efe4bff-aabc-c432-4fdb-dfa7243c6789', '09d222fa-0ecf-adf9-c4ef-51d24b215a04', 'guide', 'Guide : lire un journal d’incident', 'Les formats de journaux, les filtres grep utiles et la méthode pour relier plusieurs sources.', '/labs/guide-lecture-journaux.md', 2),
  ('27f416a4-89eb-a1de-90a9-42e34cfe3a2e', 'a4936653-9d20-d596-9a81-082087f0d3ea', 'log', 'Journal d’accès de la boutique (access-web-boutique.log)', '118 lignes au format combined : visiteurs normaux, scan, injection SQL, connexion et webshell.', '/labs/access-web-boutique.log', 1),
  ('3bea4ea0-b7dc-6f6d-e013-476cc465ab3b', 'a4936653-9d20-d596-9a81-082087f0d3ea', 'guide', 'Guide : lire un journal d’incident', 'Les formats de journaux, les filtres grep utiles et la méthode pour relier plusieurs sources.', '/labs/guide-lecture-journaux.md', 2),
  ('61781351-4db3-2121-70ce-2bd9a94f0546', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 'log', 'Journaux consolidés du SOC (incident-consolide-soc.log)', '184 lignes de deux machines, le serveur web et le pare-feu, avec du trafic normal et des faux positifs.', '/labs/incident-consolide-soc.log', 1),
  ('90e15fc8-359e-1ff4-a931-532f7638bfdd', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 'report_template', 'Modèle de rapport d’incident', 'Un squelette de rapport : résumé, chronologie, impact, remédiation.', '/labs/modele-rapport-incident.md', 2),
  ('da7e7f02-4d8e-03c5-eb8a-6014f3522f8f', 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', 'guide', 'Guide : lire un journal d’incident', 'Les formats de journaux, les filtres grep utiles et la méthode pour relier plusieurs sources.', '/labs/guide-lecture-journaux.md', 3)
insert into public.skills (id, domain_id, slug, name, description, position) values
  ('264fbdcc-d1ef-f650-08a5-d02fc8375619', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'lecture-journaux-linux', 'Lecture des journaux Linux', 'Lire /var/log, comprendre le format syslog et retrouver une ligne avec grep.', 110),
  ('fd241884-1f65-f1e5-46c6-0a0c4e58a1c1', 'de6afc0e-d8fc-2faa-3642-ae1fe39cf7fb', 'audit-droits-linux', 'Audit des droits Linux', 'Repérer les droits excessifs, les fichiers SUID, les règles sudo et les comptes cachés.', 120),
  ('af35c166-550b-28e2-822d-7a27e4b05087', '33d65715-cce7-a7f8-69f7-5a20378661d5', 'detection-bruteforce-ssh', 'Détection d’une force brute SSH', 'Distinguer un scanner d’une vraie intrusion dans un journal d’authentification.', 130),
  ('8c356ccc-3c10-cc28-ee1c-3da8b9cfdbb4', '33d65715-cce7-a7f8-69f7-5a20378661d5', 'analyse-logs-web', 'Analyse des journaux web', 'Reconnaître un scan, une injection SQL et un webshell dans un journal d’accès.', 140),
  ('48173148-79ec-3999-5db8-4b263484cc21', '33d65715-cce7-a7f8-69f7-5a20378661d5', 'reconstitution-incident', 'Reconstitution d’incident', 'Relier plusieurs sources en une chronologie et en tirer un rapport.', 150)
insert into public.skill_links (id, skill_id, kind, lesson_id, quiz_id, lab_id) values
  ('d40a1189-ab04-6c0d-f719-e912ae224f4b', '264fbdcc-d1ef-f650-08a5-d02fc8375619', 'lesson', '82d908d7-039d-ba6a-9023-f566d39a819f', null, null),
  ('c1a3c254-7de3-e7f8-6d28-6cf12e8f4deb', '264fbdcc-d1ef-f650-08a5-d02fc8375619', 'quiz', null, '84f03cb0-740f-2880-bf27-c953de89ebe6', null),
