  ('chasseur-bruteforce', 'Chasseur de force brute', 'Retrouver l’attaquant SSH, son entrée et sa persistance.', 'terminal', 'lab_completed', 1, '09d222fa-0ecf-adf9-c4ef-51d24b215a04', null, 'rare', 40, 190),
  ('analyste-web', 'Analyste web', 'Reconstituer une intrusion web, du scan au webshell.', 'eye', 'lab_completed', 1, 'a4936653-9d20-d596-9a81-082087f0d3ea', null, 'rare', 50, 200),
  ('analyste-soc', 'Analyste SOC', 'Réussir l’évaluation d’investigation : de l’accès initial à l’exfiltration.', 'shield', 'lab_completed', 1, 'df158b04-9a9d-f44f-e2a5-d3366dd066eb', null, 'epic', 60, 210),
