insert into public.mascot_lines (id, event, expression, text_fr, priority, position) values
  ('df374134-0736-2213-df0c-1178db413ca5', 'challenge', 'focused', 'Dans un journal, chaque ligne est un témoin. Cherche d’abord l’adresse qui revient trop souvent.', 4, 1010),
  ('e282253a-f4a3-9fea-3a65-ec50330cb473', 'challenge', 'mission', 'Mission d’analyste : trouve ce qui s’est passé, et prouve-le avec une ligne du fichier.', 4, 1020),
  ('463bd6b8-2caf-cfab-21d0-b8d528ce2889', 'exercise_fail', 'thinking', 'Vérifie l’heure : les journaux sont en UTC. Une heure de décalage change toute l’histoire.', 3, 1030),
  ('1ed50ce2-fb13-a77e-4713-1a5b3edd1458', 'exercise_fail', 'encouraging', 'Un faux positif t’a peut-être piégé. Cherche si l’adresse a réussi à se connecter, pas seulement essayé.', 3, 1040),
  ('6fd7b129-3f65-3b43-f76e-1dffb8b3add4', 'exercise_success', 'expert', 'Bien vu ! Une bonne réponse d’analyste s’appuie toujours sur une ligne de preuve.', 3, 1050),
  ('c141e802-ba05-10df-5c4c-e2fcd9e97d18', 'lab_complete', 'proud', 'Enquête bouclée. Pense à écrire ta chronologie : c’est la base d’un vrai rapport d’incident.', 5, 1060),
  ('31c4b118-21b2-c0ba-c32a-49c0db3e1470', 'new_skill', 'expert', 'Compétence d’investigation validée. Les équipes de sécurité cherchent exactement ce réflexe.', 6, 1070),
  ('179f965c-0df7-6c74-4565-18949dfb36ad', 'lesson_start', 'explanation', 'Un journal se lit comme une histoire : qui, quoi, quand, d’où. Garde ces quatre questions en tête.', 2, 1080)
